import{_ as o,a0 as i,w as m,s as l,I as t,x as d,a1 as n,A as p,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse(`{"title":"在 Linux 下使用 RAID（八）：當軟件 RAID 故障時如何恢復和重建數據 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下使用 RAID（八）：當軟件 RAID 故障時如何恢復和重建數據 | LCTT (RAID) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下使用 RAID（八）：當軟件 RAID 故障時如何恢復和重建數據 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下使用 RAID（八）：當軟件 RAID 故障時如何恢復和重建數據 | LCTT (RAID) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RAID/Part 8 - How to Recover Data and Rebuild Failed Software RAID's","title":"在 Linux 下使用 RAID（八）：當軟件 RAID 故障時如何恢復和重建數據","tag":"RAID","desc":""},"relativePath":"RAID/Part 8 - How to Recover Data and Rebuild Failed Software RAID's.md","filePath":"[post].md"}`),s={name:"RAID/Part 8 - How to Recover Data and Rebuild Failed Software RAID's.md"};function R(u,e,A,D,I,c){const a=i("Link");return m(),l("div",null,[e[22]||(e[22]=t("h1",{id:"在-linux-下使用-raid-八-當軟件-raid-故障時如何恢復和重建數據",tabindex:"-1"},[d("在 Linux 下使用 RAID（八）：當軟件 RAID 故障時如何恢復和重建數據 "),t("a",{class:"header-anchor",href:"#在-linux-下使用-raid-八-當軟件-raid-故障時如何恢復和重建數據","aria-label":"Permalink to “在 Linux 下使用 RAID（八）：當軟件 RAID 故障時如何恢復和重建數據”"},"​")],-1)),t("p",null,[e[1]||(e[1]=d("在閲讀過 ",-1)),n(a,{href:"https://linux.cn/article-6085-1.html"},{default:p(()=>[...e[0]||(e[0]=[d("RAID 系列",-1)])]),_:1}),e[2]||(e[2]=d(" 前面的文章後你已經對 RAID 比較熟悉了。回顧前面幾個軟件 RAID 的配置，我們對每一個都做了詳細的解釋，使用哪一個取決與你的具體情況。",-1))]),e[23]||(e[23]=t("p",null,[t("img",{src:"http://www.tecmint.com/wp-content/uploads/2015/10/Recover-Rebuild-Failed-Software-RAID.png",alt:"Recover Rebuild Failed Software RAID's"})],-1)),e[24]||(e[24]=t("p",null,[t("em",null,"恢復並重建故障的軟件 RAID - 第8部分")],-1)),e[25]||(e[25]=t("p",null,"在本文中，我們將討論當一個磁盤發生故障時如何重建軟件 RAID 陣列並且不會丟失數據。為方便起見，我們僅考慮RAID 1 的配置 - 但其方法和概念適用於所有情況。",-1)),e[26]||(e[26]=t("h4",{id:"raid-測試方案",tabindex:"-1"},[d("RAID 測試方案 "),t("a",{class:"header-anchor",href:"#raid-測試方案","aria-label":"Permalink to “RAID 測試方案”"},"​")],-1)),t("p",null,[e[4]||(e[4]=d("在進一步討論之前，請確保你已經配置好了 RAID 1 陣列，可以按照本系列第3部分提供的方法：",-1)),n(a,{href:"https://linux.cn/article-6093-1.html"},{default:p(()=>[...e[3]||(e[3]=[d("在 Linux 中如何創建 RAID 1（鏡像）",-1)])]),_:1}),e[5]||(e[5]=d("。",-1))]),e[27]||(e[27]=r(`<p>在目前的情況下，僅有的變化是：</p><ol><li>使用不同版本 CentOS（v7），而不是前面文章中的（v6.5）。</li><li>磁盤容量發生改變， /dev/sdb 和 /dev/sdc（各8GB）。</li></ol><p>此外，如果 SELinux 設置為 enforcing 模式，你需要將相應的標籤添加到掛載 RAID 設備的目錄中。否則，當你試圖掛載時，你會碰到這樣的警告信息：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/SELinux-RAID-Mount-Error.png" alt="SELinux RAID Mount Error"></p><p><em>啓用 SELinux 時 RAID 掛載錯誤</em></p><p>通過以下命令來解決:</p><pre><code># restorecon -R /mnt/raid1
</code></pre><h3 id="配置-raid-監控" tabindex="-1">配置 RAID 監控 <a class="header-anchor" href="#配置-raid-監控" aria-label="Permalink to “配置 RAID 監控”">​</a></h3><p>存儲設備損壞的原因很多（儘管固態硬盤大大減少了這種情況發生的可能性），但不管是什麼原因，可以肯定問題隨時可能發生，你需要準備好替換髮生故障的部分，並確保數據的可用性和完整性。</p><p>首先建議是。雖然你可以查看 <code>/proc/mdstat</code> 來檢查 RAID 的狀態，但有一個更好的和節省時間的方法，使用監控 + 掃描模式運行 mdadm，它將警報通過電子郵件發送到一個預定義的收件人。</p><p>要這樣設置，在 <code>/etc/mdadm.conf</code> 添加以下行：</p><pre><code>MAILADDR user@&lt;domain or localhost&gt;
</code></pre><p>我自己的設置如下：</p><pre><code>MAILADDR gacanepa@localhost
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/RAID-Monitoring-Email-Alerts.png" alt="RAID Monitoring Email Alerts"></p><p><em>監控 RAID 並使用電子郵件進行報警</em></p><p>要讓 mdadm 運行在監控 + 掃描模式中，以 root 用户添加以下 crontab 條目：</p><pre><code>@reboot /sbin/mdadm --monitor --scan --oneshot
</code></pre><p>默認情況下，mdadm 每隔60秒會檢查 RAID 陣列，如果發現問題將發出警報。你可以通過添加 <code>--delay</code> 選項到crontab 條目上面，後面跟上秒數，來修改默認行為（例如，<code>--delay</code> 1800意味着30分鐘）。</p>`,19)),t("p",null,[e[7]||(e[7]=d("最後，確保你已經安裝了一個郵件用户代理（MUA），如",-1)),n(a,{href:"http://www.tecmint.com/send-mail-from-command-line-using-mutt-command/"},{default:p(()=>[...e[6]||(e[6]=[d("mutt 或 mailx",-1)])]),_:1}),e[8]||(e[8]=d("。否則，你將不會收到任何警報。",-1))]),e[28]||(e[28]=r(`<p>在一分鐘內，我們就會看到 mdadm 發送的警報。</p><h3 id="模擬和更換髮生故障的-raid-存儲設備" tabindex="-1">模擬和更換髮生故障的 RAID 存儲設備 <a class="header-anchor" href="#模擬和更換髮生故障的-raid-存儲設備" aria-label="Permalink to “模擬和更換髮生故障的 RAID 存儲設備”">​</a></h3><p>為了給 RAID 陣列中的存儲設備模擬一個故障，我們將使用 <code>--manage</code> 和 <code>--set-faulty</code> 選項，如下所示：</p><pre><code># mdadm --manage --set-faulty /dev/md0 /dev/sdc1  
</code></pre><p>這將導致 /dev/sdc1 被標記為 faulty，我們可以在 /proc/mdstat 看到：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Stimulate-Issue-with-RAID-Storage.png" alt="Stimulate Issue with RAID Storage"></p><p><em>在 RAID 存儲設備上模擬問題</em></p><p>更重要的是，讓我們看看是不是收到了同樣的警報郵件：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Email-Alert-on-Failed-RAID-Device.png" alt="Email Alert on Failed RAID Device"></p><p><em>RAID 設備故障時發送郵件警報</em></p><p>在這種情況下，你需要從軟件 RAID 陣列中刪除該設備：</p><pre><code># mdadm /dev/md0 --remove /dev/sdc1
</code></pre><p>然後，你可以直接從機器中取出，並將其使用備用設備來取代（/dev/sdd 中類型為 fd 的分區是以前創建的）：</p><pre><code># mdadm --manage /dev/md0 --add /dev/sdd1
</code></pre><p>幸運的是，該系統會使用我們剛才添加的磁盤自動重建陣列。我們可以通過標記 /dev/sdb1 為 faulty 來進行測試，從陣列中取出後，並確認 tecmint.txt 文件仍然在 /mnt/raid1 是可訪問的：</p><pre><code># mdadm --detail /dev/md0
# mount | grep raid1
# ls -l /mnt/raid1 | grep tecmint
# cat /mnt/raid1/tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Rebuilding-RAID-Array.png" alt="Confirm Rebuilding RAID Array"></p><p><em>確認 RAID 重建</em></p><p>上面圖片清楚的顯示，添加 /dev/sdd1 到陣列中來替代 /dev/sdc1，數據的重建是系統自動完成的，不需要干預。</p><p>雖然要求不是很嚴格，有一個備用設備是個好主意，這樣更換故障的設備就可以在瞬間完成了。要做到這一點，先讓我們重新添加 /dev/sdb1 和 /dev/sdc1：</p><pre><code># mdadm --manage /dev/md0 --add /dev/sdb1
# mdadm --manage /dev/md0 --add /dev/sdc1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Replace-Failed-Raid-Device.png" alt="Replace Failed Raid Device"></p><p><em>取代故障的 Raid 設備</em></p><h3 id="從冗餘丟失中恢復數據" tabindex="-1">從冗餘丟失中恢復數據 <a class="header-anchor" href="#從冗餘丟失中恢復數據" aria-label="Permalink to “從冗餘丟失中恢復數據”">​</a></h3><p>如前所述，當一個磁盤發生故障時， mdadm 將自動重建數據。但是，如果陣列中的2個磁盤都故障時會發生什麼？讓我們來模擬這種情況，通過標記 /dev/sdb1 和 /dev/sdd1 為 faulty：</p><pre><code># umount /mnt/raid1
# mdadm --manage --set-faulty /dev/md0 /dev/sdb1
# mdadm --stop /dev/md0
# mdadm --manage --set-faulty /dev/md0 /dev/sdd1
</code></pre><p>此時嘗試以同樣的方式重新創建陣列就（或使用 <code>--assume-clean</code> 選項）可能會導致數據丟失，因此不到萬不得已不要使用。</p><p>讓我們試着從 /dev/sdb1 恢復數據，例如，在一個類似的磁盤分區（/dev/sde1 - 注意，這需要你執行前在/dev/sde 上創建一個 fd 類型的分區）上使用 <code>ddrescue</code>：</p><pre><code># ddrescue -r 2 /dev/sdb1 /dev/sde1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Recovering-Raid-Array.png" alt="Recovering Raid Array"></p><p><em>恢復 Raid 陣列</em></p><p>請注意，到現在為止，我們還沒有觸及 /dev/sdb 和 /dev/sdd，這是 RAID 陣列的一部分分區。</p><p>現在，讓我們使用 /dev/sde1 和 /dev/sdf1 來重建陣列：</p><pre><code># mdadm --create /dev/md0 --level=mirror --raid-devices=2 /dev/sd[e-f]1
</code></pre><p>請注意，在真實的情況下，你需要使用與原來的陣列中相同的設備名稱，即設備失效後替換的磁盤的名稱應該是 /dev/sdb1 和 /dev/sdc1。</p><p>在本文中，我選擇了使用額外的設備來重新創建全新的磁盤陣列，是為了避免與原來的故障磁盤混淆。</p><p>當被問及是否繼續寫入陣列時，鍵入 Y，然後按 Enter。陣列被啓動，你也可以查看它的進展：</p><pre><code># watch -n 1 cat /proc/mdstat
</code></pre><p>當這個過程完成後，你就應該能夠訪問 RAID 的數據：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Raid-Content.png" alt="Confirm Raid Content"></p><p><em>確認 Raid 數據</em></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在本文中，我們回顧了從 RAID 故障和冗餘丟失中恢復數據。但是，你要記住，這種技術是一種存儲解決方案，不能取代備份。</p><p>本文中介紹的方法適用於所有 RAID 中，其中的概念我將在本系列的最後一篇（RAID 管理）中涵蓋它。</p><p>如果你對本文有任何疑問，隨時給我們以評論的形式説明。我們期待傾聽閣下的心聲！</p><hr>`,46)),t("p",null,[e[10]||(e[10]=d("via: ",-1)),n(a,{href:"http://www.tecmint.com/recover-data-and-rebuild-failed-software-raid/"},{default:p(()=>[...e[9]||(e[9]=[d("http://www.tecmint.com/recover-data-and-rebuild-failed-software-raid/",-1)])]),_:1})]),t("p",null,[e[14]||(e[14]=d("作者：",-1)),n(a,{href:"http://www.tecmint.com/author/gacanepa/"},{default:p(()=>[...e[11]||(e[11]=[d("Gabriel Cánepa",-1)])]),_:1}),e[15]||(e[15]=d(" 譯者：",-1)),n(a,{href:"https://github.com/strugglingyouth"},{default:p(()=>[...e[12]||(e[12]=[d("strugglingyouth",-1)])]),_:1}),e[16]||(e[16]=d(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:p(()=>[...e[13]||(e[13]=[d("wxy",-1)])]),_:1})]),t("p",null,[e[19]||(e[19]=d("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[17]||(e[17]=[d("LCTT",-1)])]),_:1}),e[20]||(e[20]=d(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:p(()=>[...e[18]||(e[18]=[d("Linux中國",-1)])]),_:1}),e[21]||(e[21]=d(" 榮譽推出",-1))])])}const g=o(s,[["render",R]]);export{f as __pageData,g as default};
